<?php
$adminUrl=is_callable($adminUrl??null)?$adminUrl:static fn(string $path=''):string=>'/'.trim($path,'/');$workspace=is_array($workspace??null)?$workspace:[];$items=$workspace['items']??[];$filters=is_array($filters??null)?$filters:[];$forms=is_array($forms??null)?$forms:[];$noticeMessages=['reviewed'=>'Submission marked reviewed.','deleted'=>'Submission deleted permanently.'];$notice=is_scalar($notice??null)?($noticeMessages[(string)$notice]??null):null;$error=is_scalar($error??null)?(string)$error:'';$page=(int)($filters['page']??1);$perPage=(int)($filters['per_page']??25);$total=(int)($workspace['total']??0);$pages=max(1,(int)ceil($total/max(1,$perPage)));$query=static function(int $target)use($filters):string{return http_build_query(array_filter(['q'=>$filters['q']??null,'form_id'=>$filters['form_id']??null,'status'=>$filters['status']??null,'per_page'=>$filters['per_page']??null,'page'=>$target],static fn($v)=>$v!==null&&$v!==''));};
?>
<section class="admin-content-page" aria-labelledby="submission-list-title"><header class="admin-content-header"><div class="admin-content-header__copy"><p class="admin-content-eyebrow">Form Manager</p><h2 id="submission-list-title">Submissions</h2><p>Inspect retained form submissions and their review state.</p></div><a class="admin-button admin-button--secondary" href="<?=htmlspecialchars($adminUrl('forms'),ENT_QUOTES,'UTF-8')?>">Back to forms</a></header><?php if($notice):?><div class="admin-alert admin-alert--success" role="status"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error!==''):?><div class="admin-alert admin-alert--danger" role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="admin-panel admin-content-table-panel" aria-labelledby="submission-workspace-title"><header class="admin-content-table-panel__header"><div><h3 id="submission-workspace-title">Retained submissions</h3><p><?=$total?> submission<?=$total===1?'':'s'?>.</p></div></header><form class="admin-form admin-content-filters form-manager-workspace-filters" method="get" action="<?=htmlspecialchars($workspaceUrl??$adminUrl('forms/submissions'),ENT_QUOTES,'UTF-8')?>"><div class="admin-content-filter-field admin-content-search"><label for="submission-search">Search form names</label><input id="submission-search" name="q" type="search" value="<?=htmlspecialchars((string)($filters['q']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-content-filter-field"><label for="submission-form">Form</label><select id="submission-form" name="form_id"><option value="">All forms</option><?php foreach($forms as $form):?><option value="<?=$form->id()->value()?>" <?=($filters['form_id']??null)===$form->id()->value()?'selected':''?>><?=htmlspecialchars($form->name(),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div><div class="admin-content-filter-field"><label for="submission-status">Status</label><select id="submission-status" name="status"><option value="">All statuses</option><option value="new" <?=($filters['status']??null)==='new'?'selected':''?>>New</option><option value="reviewed" <?=($filters['status']??null)==='reviewed'?'selected':''?>>Reviewed</option></select></div><div class="admin-content-filter-field"><label for="submission-per-page">Per page</label><input id="submission-per-page" name="per_page" type="number" min="1" max="100" value="<?=htmlspecialchars((string)$perPage,ENT_QUOTES,'UTF-8')?>"></div><div class="admin-content-filter-actions"><button class="admin-button admin-button--secondary" type="submit">Apply filters</button></div></form><?php if($items===[]):?><div class="admin-empty-state"><h3 class="admin-empty-state__title">No submissions found</h3><p class="admin-empty-state__description">No retained submissions match the current filters.</p></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th scope="col">Form</th><th scope="col">Status</th><th scope="col">Received</th><th scope="col">Updated</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td data-label="Form"><?=htmlspecialchars((string)$item['form_name'],ENT_QUOTES,'UTF-8')?></td><td data-label="Status"><?=htmlspecialchars(ucfirst((string)$item['status']),ENT_QUOTES,'UTF-8')?></td><td data-label="Received"><?=htmlspecialchars((string)$item['created_at'],ENT_QUOTES,'UTF-8')?></td><td data-label="Updated"><?=htmlspecialchars((string)$item['updated_at'],ENT_QUOTES,'UTF-8')?></td><td data-label="Actions"><div class="admin-actions"><a class="admin-button admin-button--link" href="<?=htmlspecialchars($adminUrl('forms/submissions/'.(int)$item['id']),ENT_QUOTES,'UTF-8')?>">View submission</a><?php if(!empty($canDelete)):?><form method="post" action="<?=htmlspecialchars($adminUrl('forms/submissions/'.(int)$item['id'].'/delete'),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="_token" value="<?=htmlspecialchars((string)($csrfToken??''),ENT_QUOTES,'UTF-8')?>"><button class="admin-button admin-button--link" type="submit">Delete submission permanently</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($pages>1):?><nav class="admin-actions" aria-label="Submission pagination"><?php if($page>1):?><a class="admin-button admin-button--secondary" href="<?=htmlspecialchars(($workspaceUrl??$adminUrl('forms/submissions')).'?'.$query($page-1),ENT_QUOTES,'UTF-8')?>">Previous</a><?php endif;?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):?><a class="admin-button admin-button--secondary" href="<?=htmlspecialchars(($workspaceUrl??$adminUrl('forms/submissions')).'?'.$query($page+1),ENT_QUOTES,'UTF-8')?>">Next</a><?php endif;?></nav><?php endif;?></section></section>
